import re
import json
from urllib.parse import unquote
import sys

def decode_notebook_full(filename):
    """Fully decode and parse notebook model"""
    with open(filename, 'rb') as f:
        content = f.read().decode('utf-8', errors='ignore')

    match = re.search(r"__DATABRICKS_NOTEBOOK_MODEL = '([^']+)'", content)
    if not match:
        return None

    # URL decode multiple times until stable
    encoded = match.group(1)
    current = encoded
    for iteration in range(5):
        decoded = unquote(current)
        if decoded == current:
            break
        current = decoded

    # Try JSON parse
    try:
        notebook = json.loads(current)
        return notebook
    except Exception as e:
        # Maybe it's still partial - try to extract meaningful content
        print(f"JSON parse error: {e}", file=sys.stderr)
        # Find command sections manually
        commands = re.findall(r'"command":"([^"]*(?:\\.[^"]*)*)"', current)
        return {"commands": [{"command": c} for c in commands[:10]]}

# Try decoding
for fname in ['rmd_template.html', 'ld_template.html', 'od_template.html']:
